from zipfile import ZipFile
import re, xml.etree.ElementTree as ET
from pathlib import Path
ns={'a':'http://schemas.openxmlformats.org/drawingml/2006/main','p':'http://schemas.openxmlformats.org/presentationml/2006/main'}

def extract_ppt_text(path):
    out=[]
    with ZipFile(path) as z:
        slides=sorted([n for n in z.namelist() if n.startswith('ppt/slides/slide') and n.endswith('.xml') and '/_rels/' not in n], key=lambda x:int(re.search(r'slide(\d+)\.xml',x).group(1)))
        for s in slides:
            xml=z.read(s)
            root=ET.fromstring(xml)
            texts=[]
            for t in root.findall('.//a:t',ns):
                if t.text:
                    texts.append(t.text)
            out.append(texts)
    return out

for path in ['assets/ppt_pack/ca327de5_20260305大组会-颜雍颀-v5_最终交付.pptx','assets/ppt_pack/1c8b74da_literature_report_FINAL_v2-1.pptx']:
    print('\n====',path,'====')
    slides=extract_ppt_text(path)
